-- PLATFORM_SQL 0041_room_bookings_shape
--
-- Brings the Django stub room_bookings to the shape its Drizzle declaration reads and writes (26 columns missing,
-- among them organization_id, booked_by, start_time, end_time and status) so the booking rules in
-- lib/services/room-booking-rules.ts can be enforced by a route, and settles double booking in the database:
-- a trigger locks the room row and refuses a booking that overlaps an active booking of the same room (SQLSTATE
-- 23P01). The first part is generated by scripts/generate-stub-evolution.ts: additive nullable columns with declared
-- defaults; NOT NULL only while the relation is empty. The shape is only correct for an empty table; a populated
-- stub keeps nullable columns. No foreign keys and no RLS here: tenant isolation is cache migration 0035 and the
-- storage-authority manifest. Registered UNQUALIFIED. Not applied here; native PostgreSQL execution is
-- READY_FOR_VS_EXECUTION.
--> statement-breakpoint
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_type t JOIN pg_namespace s ON s.oid = t.typnamespace WHERE t.typname = 'event_status' AND s.nspname = 'public') THEN CREATE TYPE public."event_status" AS ENUM ('scheduled', 'confirmed', 'cancelled', 'completed', 'no_show', 'rescheduled'); END IF; END $$;
--> statement-breakpoint
-- room_bookings
--> statement-breakpoint
DO $$ BEGIN IF to_regclass('public.room_bookings') IS NULL THEN RAISE EXCEPTION 'platform stub evolution fail-closed: public.room_bookings does not exist.'; END IF; END $$;
--> statement-breakpoint
ALTER TABLE public."room_bookings"
  ADD COLUMN IF NOT EXISTS "event_id" uuid,
  ADD COLUMN IF NOT EXISTS "organization_id" uuid,
  ADD COLUMN IF NOT EXISTS "booked_by" text,
  ADD COLUMN IF NOT EXISTS "booked_for" text,
  ADD COLUMN IF NOT EXISTS "purpose" text,
  ADD COLUMN IF NOT EXISTS "start_time" timestamp,
  ADD COLUMN IF NOT EXISTS "end_time" timestamp,
  ADD COLUMN IF NOT EXISTS "setup_required" boolean DEFAULT false,
  ADD COLUMN IF NOT EXISTS "setup_time" integer DEFAULT 0,
  ADD COLUMN IF NOT EXISTS "catering_required" boolean DEFAULT false,
  ADD COLUMN IF NOT EXISTS "catering_notes" text,
  ADD COLUMN IF NOT EXISTS "special_requests" text,
  ADD COLUMN IF NOT EXISTS "status" event_status DEFAULT 'scheduled',
  ADD COLUMN IF NOT EXISTS "requires_approval" boolean DEFAULT false,
  ADD COLUMN IF NOT EXISTS "approved_by" text,
  ADD COLUMN IF NOT EXISTS "approved_at" timestamp,
  ADD COLUMN IF NOT EXISTS "approval_notes" text,
  ADD COLUMN IF NOT EXISTS "checked_in_at" timestamp,
  ADD COLUMN IF NOT EXISTS "checked_in_by" text,
  ADD COLUMN IF NOT EXISTS "checked_out_at" timestamp,
  ADD COLUMN IF NOT EXISTS "actual_end_time" timestamp,
  ADD COLUMN IF NOT EXISTS "cancelled_at" timestamp,
  ADD COLUMN IF NOT EXISTS "cancelled_by" text,
  ADD COLUMN IF NOT EXISTS "cancellation_reason" text,
  ADD COLUMN IF NOT EXISTS "attendee_count" integer,
  ADD COLUMN IF NOT EXISTS "metadata" jsonb;
