DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'room_bookings' AND column_name = 'id' AND column_default IS NULL) THEN
      ALTER TABLE public."room_bookings" ALTER COLUMN "id" SET DEFAULT gen_random_uuid();
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'room_bookings' AND column_name = 'created_at' AND column_default IS NULL) THEN
      ALTER TABLE public."room_bookings" ALTER COLUMN "created_at" SET DEFAULT now();
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'room_bookings' AND column_name = 'updated_at' AND column_default IS NULL) THEN
      ALTER TABLE public."room_bookings" ALTER COLUMN "updated_at" SET DEFAULT now();
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."room_bookings") THEN
      ALTER TABLE public."room_bookings"
        ALTER COLUMN "organization_id" SET NOT NULL,
        ALTER COLUMN "booked_by" SET NOT NULL,
        ALTER COLUMN "purpose" SET NOT NULL,
        ALTER COLUMN "start_time" SET NOT NULL,
        ALTER COLUMN "end_time" SET NOT NULL;
    END IF;
END $$;

--> statement-breakpoint
DO $$
BEGIN
  IF to_regclass('public.room_bookings') IS NOT NULL THEN
    CREATE INDEX IF NOT EXISTS idx_room_bookings_room_time ON public.room_bookings (room_id, start_time, end_time);
    CREATE INDEX IF NOT EXISTS idx_room_bookings_org ON public.room_bookings (organization_id);
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'room_bookings_time_order' AND conrelid = 'public.room_bookings'::regclass) THEN
      ALTER TABLE public.room_bookings ADD CONSTRAINT room_bookings_time_order CHECK (end_time > start_time) NOT VALID;
    END IF;
  END IF;
END $$;
--> statement-breakpoint
DO $$
BEGIN
  IF to_regclass('public.room_bookings') IS NOT NULL AND to_regclass('public.meeting_rooms') IS NOT NULL THEN
    CREATE OR REPLACE FUNCTION public.enforce_room_booking_no_overlap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
    BEGIN
      IF COALESCE(NEW.status::text, 'scheduled') IN ('cancelled', 'completed', 'no_show', 'rescheduled') THEN
        RETURN NEW;
      END IF;
      IF NEW.start_time IS NULL OR NEW.end_time IS NULL THEN
        RETURN NEW;
      END IF;
      -- Holding the room row serialises bookings for the same room, so the overlap test below is not stale.
      PERFORM 1 FROM public.meeting_rooms WHERE id = NEW.room_id FOR UPDATE;
      IF EXISTS (
        SELECT 1 FROM public.room_bookings b
        WHERE b.room_id = NEW.room_id
          AND b.id IS DISTINCT FROM NEW.id
          AND COALESCE(b.status::text, 'scheduled') IN ('scheduled', 'confirmed')
          AND b.start_time < NEW.end_time
          AND b.end_time > NEW.start_time
      ) THEN
        RAISE EXCEPTION 'room is already booked for that time' USING ERRCODE = '23P01', CONSTRAINT = 'room_bookings_no_overlap';
      END IF;
      RETURN NEW;
    END
    $fn$;
    REVOKE ALL ON FUNCTION public.enforce_room_booking_no_overlap() FROM PUBLIC;
    DROP TRIGGER IF EXISTS trg_room_bookings_no_overlap ON public.room_bookings;
    CREATE TRIGGER trg_room_bookings_no_overlap
      BEFORE INSERT OR UPDATE OF status, start_time, end_time, room_id ON public.room_bookings
      FOR EACH ROW EXECUTE FUNCTION public.enforce_room_booking_no_overlap();
  END IF;
END $$;